  "7at":[{"la":"El-mou3allem dkhal lel-bit w *7at* el-ktab 3la et-tawla.","en":"The teacher came into the room and put the book on the table.","lv":2}],
  "tawla":[{"la":"El-mou3allem dkhal lel-bit w 7at el-ktab 3la *et-tawla*.","en":"The teacher came into the room and put the book on the table.","lv":2},{"la":"Es-sekkina 3la *et-tawla* jenb el-mo3al9a w es-sa7n.","en":"The knife is on the table next to the spoon and the plate.","lv":3}],
  "nsa":[{"la":"*Nsit* el-mefte7 fi ech-chkara!","en":"I forgot the key in the bag!","lv":2}],
