  "sa9 (leg)":[{"la":"*Sa9i* mridha w ma nnajjemch nejri.","en":"My leg is hurt and I can't run.","lv":2},{"la":"El-ghani 3andou karhba sri3a w el-meskin yemchi 3la *sa9ih*.","en":"The rich man has a fast car and the poor man goes on foot.","lv":3}],
  "jra":[{"la":"Sa9i mridha w ma nnajjemch *nejri*.","en":"My leg is hurt and I can't run.","lv":2},{"la":"Sami *jra* fisa3 w n9ez fou9 el-koura.","en":"Sami ran fast and jumped over the ball.","lv":3},{"la":"Khoft w *jrit* fisa3 led-dar.","en":"I was afraid and ran home fast.","lv":4}],
  "bka":[{"la":"Et-tfol *bka* w ba3d dh7ak.","en":"The boy cried and then laughed.","lv":2},{"la":"El-weld el-ghabi dhrab el-jar w ommou *bket*.","en":"The stupid boy hit the neighbour and his mum cried.","lv":4}],
