  "ghda":[{"la":"Stanna chwaya, *el-ghda* 9rib.","en":"Wait a little, lunch is near.","lv":2}],
  "9rib":[{"la":"Stanna chwaya, el-ghda *9rib*.","en":"Wait a little, lunch is near.","lv":2}],
  "sbe7":[{"la":"Fi *es-sbe7* nekel fter, fi el-3chiya nekel 3cha.","en":"In the morning I eat breakfast, in the evening I eat dinner.","lv":2},{"la":"Naddhaft ed-dar wa7di fi *es-sbe7*.","en":"I cleaned the house by myself in the morning.","lv":4}],
