  "3cha":[{"la":"Fi es-sbe7 nekel fter, fi el-3chiya nekel *3cha*.","en":"In the morning I eat breakfast, in the evening I eat dinner.","lv":2},{"la":"Ommi tayybet *3cha* 7ar bel-harissa, w bes7a!","en":"Mum cooked a spicy dinner with harissa, and enjoy!","lv":4}],
  "kosksi":[{"la":"Chrit *kosksi* w mel7 w sokkor men es-souk.","en":"I bought couscous, salt and sugar from the market.","lv":2},{"la":"Tlobt *kosksi* bed-djej men el-mat3am.","en":"I ordered couscous with chicken from the restaurant.","lv":4}],
