  "l9a":[{"la":"*L9it* stilou ta7t et-tawla.","en":"I found a pen under the table.","lv":2},{"la":"Fakkert fi souel s3ib w *l9it* el-jweb.","en":"I thought about a hard question and found the answer.","lv":3}],
  "stilou":[{"la":"L9it *stilou* ta7t et-tawla.","en":"I found a pen under the table.","lv":2}],
  "ta7t":[{"la":"L9it stilou *ta7t* et-tawla.","en":"I found a pen under the table.","lv":2}],
  "bda":[{"la":"*Bdit* el-khedma fi es-sbe7 w kammaltha fi el-lil.","en":"I started the work in the morning and finished it at night.","lv":2}],
