  "ya":[{"la":"*Ya* Ali, 3awenni min fadhlek!","en":"Ali, help me please!","lv":2},{"la":"Ommi 9alet: \"Y3aychek *ya* Karim, enti rajel mezyen.\"","en":"Mum said: \"Thank you Karim, you are a good man.\"","lv":4}],
  "3awen":[{"la":"Ya Ali, *3awenni* min fadhlek!","en":"Ali, help me please!","lv":2}],
