  "y3aychek":[{"la":"*Y3aychek*! 3afwen.","en":"Thank you! You're welcome.","lv":2},{"la":"Rabbi *y3aychek*! Barak allahou fik.","en":"God keep you! Thank you very much.","lv":3},{"la":"Ommi 9alet: \"*Y3aychek* ya Karim, enti rajel mezyen.\"","en":"Mum said: \"Thank you Karim, you are a good man.\"","lv":4}],
