  "7azin":[{"la":"Sa7bti Amina *7azina* khater khalha mridh.","en":"My friend Amina is sad because her uncle is ill.","lv":2},{"la":"Tfakkert jedda w 9albi *7azin*.","en":"I remembered grandma and my heart was sad.","lv":3}],
